import { readFileSync } from "node:fs";
import { EmailAddress } from "@surveybeat/domain";
import * as Schema from "effect/Schema";
import { parse } from "yaml";

/** The checked-in allowlist file, keyed by stage, with `default` for every stage not listed. */
export const allowlistFile = new URL("org-creation-allowlist.yaml", import.meta.url);

const AllowlistFile = Schema.Record(Schema.String, Schema.NonEmptyArray(EmailAddress));

/**
 * The `ORG_CREATION_ALLOWLIST` value for one stage: its emails, comma-separated.
 * Throws when the file is malformed or names no list for the stage, so a deploy never binds an empty list.
 */
export const allowlistForStage = (yamlText: string, stage: string): string => {
  const lists = Schema.decodeUnknownSync(AllowlistFile)(parse(yamlText));
  const emails = lists[stage] ?? lists["default"];
  if (emails === undefined) {
    throw new Error(`org-creation-allowlist.yaml has no entry for stage "${stage}" and no "default" entry`);
  }
  return emails.join(",");
};

export const readAllowlistForStage = (stage: string): string =>
  allowlistForStage(readFileSync(allowlistFile, "utf8"), stage);

import { assert, describe, it } from "@effect/vitest";
import { allowlistForStage, readAllowlistForStage } from "./orgCreationAllowlist.ts";

const file = `
production:
  - owner@example.com
  - second@example.com
default:
  - dev@example.com
`;

describe("allowlistForStage", () => {
  it("joins the stage's own emails", () => {
    assert.strictEqual(allowlistForStage(file, "production"), "owner@example.com,second@example.com");
  });

  it("falls back to default for a stage without an entry", () => {
    assert.strictEqual(allowlistForStage(file, "pr-74"), "dev@example.com");
  });

  it("refuses a stage with neither its own entry nor default", () => {
    assert.throws(() => allowlistForStage("production:\n  - owner@example.com\n", "staging"), /no entry/);
  });

  it("refuses an empty list", () => {
    assert.throws(() => allowlistForStage("production: []\ndefault:\n  - dev@example.com\n", "production"));
  });

  it("refuses something that is not an email", () => {
    assert.throws(() => allowlistForStage("default:\n  - not-an-email\n", "pr-1"));
  });

  it("reads the checked-in file for every deployed stage", () => {
    for (const stage of ["production", "staging", "pr-1", "dev-someone"]) {
      assert.notStrictEqual(readAllowlistForStage(stage), "");
    }
  });
});

