export type TrendPoint = typeof TrendPoint.Type;

/** One historical point on a Dimension's trend line over up to 12 Rounds. */
export const DimensionTrendPoint = Schema.Struct({
  roundId: RoundId,
  plannedOpenDate: Schema.String,
